 "content": "def transform(grid):
    """Boundary 1-markers cast full row/column rays; touched 2-objects turn to 1."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    rows = {r for r in range(h) if grid[r][0] == 1 or grid[r][w - 1] == 1}
    cols = {c for c in range(w) if grid[0][c] == 1 or grid[h - 1][c] == 1}

    # Identify original 4-connected 2-components contacted by a marker ray.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            touched = False
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                if rr in rows or cc in cols:
                    touched = True
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if touched:
                for rr, cc in component:
                    out[rr][cc] = 1

    # Rays are drawn last, including over any contacted objects.
    for r in rows:
        out[r] = [1] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(',', ':')))
