 "content": "def transform(grid):
    """Draw rays from boundary 1s; recolor every 4-connected 2-object hit by a ray."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ray_rows = {r for r in range(h) if grid[r][0] == 1 or grid[r][w - 1] == 1}
    ray_cols = {c for c in range(w) if grid[0][c] == 1 or grid[h - 1][c] == 1}

    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            touched = False
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                if rr in ray_rows or cc in ray_cols:
                    touched = True
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if touched:
                for rr, cc in component:
                    out[rr][cc] = 1

    for r in ray_rows:
        out[r] = [1] * w
    for c in ray_cols:
        for r in range(h):
            out[r][c] = 1
    return out

