 "content": "def transform(grid):
    """Extend every boundary 1 across its row or column, overwriting crossed cells."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        if grid[r][0] == 1 or grid[r][w - 1] == 1:
            out[r] = [1] * w
    for c in range(w):
        if grid[0][c] == 1 or grid[h - 1][c] == 1:
            for r in range(h):
                out[r][c] = 1
    return out

